class Solution {
public:
    int minimumSeconds(vector<vector<string>>& land) {
        int R = land.size(), C = land[0].size();
        vector<vector<int>> water_time(R, vector<int>(C, 1e9));
        queue<pair<int, int>> wq;
        int sr = 0, sc = 0;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (land[r][c] == "*") {
                    water_time[r][c] = 0;
                    wq.push({r, c});
                } else if (land[r][c] == "S") {
                    sr = r; sc = c;
                }
            }
        }
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!wq.empty()) {
            auto [r, c] = wq.front(); wq.pop();
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && land[nr][nc] == "." && water_time[nr][nc] == 1e9) {
                    water_time[nr][nc] = water_time[r][c] + 1;
                    wq.push({nr, nc});
                }
            }
        }
        queue<tuple<int, int, int>> pq;
        vector<vector<bool>> vis(R, vector<bool>(C, false));
        pq.push({sr, sc, 0});
        vis[sr][sc] = true;
        while (!pq.empty()) {
            auto [r, c, t] = pq.front(); pq.pop();
            if (land[r][c] == "D") return t;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && !vis[nr][nc]) {
                    if ((land[nr][nc] == "." || land[nr][nc] == "D") && t + 1 < water_time[nr][nc]) {
                        vis[nr][nc] = true;
                        pq.push({nr, nc, t + 1});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minimumSeconds(List<List<String>> land) {
        int R = land.size(), C = land.get(0).size();
        int[][] waterTime = new int[R][C];
        for (int[] row : waterTime) Arrays.fill(row, Integer.MAX_VALUE);
        Queue<int[]> wq = new LinkedList<>();
        int sr = 0, sc = 0;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                String cell = land.get(r).get(c);
                if (cell.equals("*")) {
                    waterTime[r][c] = 0;
                    wq.add(new int[]{r, c});
                } else if (cell.equals("S")) {
                    sr = r; sc = c;
                }
            }
        }
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!wq.isEmpty()) {
            int[] curr = wq.poll();
            int r = curr[0], c = curr[1];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && land.get(nr).get(nc).equals(".") && waterTime[nr][nc] == Integer.MAX_VALUE) {
                    waterTime[nr][nc] = waterTime[r][c] + 1;
                    wq.add(new int[]{nr, nc});
                }
            }
        }
        Queue<int[]> pq = new LinkedList<>();
        boolean[][] vis = new boolean[R][C];
        pq.add(new int[]{sr, sc, 0});
        vis[sr][sc] = true;
        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int r = curr[0], c = curr[1], t = curr[2];
            if (land.get(r).get(c).equals("D")) return t;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && !vis[nr][nc]) {
                    String nextCell = land.get(nr).get(nc);
                    if ((nextCell.equals(".") || nextCell.equals("D")) && t + 1 < waterTime[nr][nc]) {
                        vis[nr][nc] = true;
                        pq.add(new int[]{nr, nc, t + 1});
                    }
                }
            }
        }
        return -1;
    }
}

