var minimumSeconds = function(land) {
    const R = land.length, C = land[0].length;
    const waterTime = Array.from({ length: R }, () => new Array(C).fill(Infinity));
    const wq = [];
    let wHead = 0;
    let sr = 0, sc = 0;
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            if (land[r][c] === '*') {
                waterTime[r][c] = 0;
                wq.push([r, c]);
            } else if (land[r][c] === 'S') {
                sr = r; sc = c;
            }
        }
    }
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (wHead < wq.length) {
        const [r, c] = wq[wHead++];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && land[nr][nc] === '.' && waterTime[nr][nc] === Infinity) {
                waterTime[nr][nc] = waterTime[r][c] + 1;
                wq.push([nr, nc]);
            }
        }
    }
    const pq = [[sr, sc, 0]];
    let pHead = 0;
    const vis = Array.from({ length: R }, () => new Array(C).fill(false));
    vis[sr][sc] = true;
    while (pHead < pq.length) {
        const [r, c, t] = pq[pHead++];
        if (land[r][c] === 'D') return t;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && !vis[nr][nc]) {
                if ((land[nr][nc] === '.' || land[nr][nc] === 'D') && t + 1 < waterTime[nr][nc]) {
                    vis[nr][nc] = true;
                    pq.push([nr, nc, t + 1]);
                }
            }
        }
    }
    return -1;
};
